package com.exe201.rrms.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Data @NoArgsConstructor public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long actorId; private String action; private String targetType; private Long targetId; @Column(columnDefinition="TEXT") private String details; private LocalDateTime createdAt; @PrePersist void p(){createdAt=LocalDateTime.now();} }